  1234	/**
  1235	 * @brief 把"帧外增量还没进 R"的记账补烘掉（限频窗口内先留着）。
  1236	 *
  1237	 * @details 由 200 ms 的航向拍调用（`vmap_view_set_heading`），所以即使某次增量
  1238	 *          之后再没有任何失效，内容也会在窗口到期后的下一拍上屏；不会永远停在旧版本。
  1239	 */
  1240	static void vmap_rot_service(vmap_view_t * view)
  1241	{
  1242	    bool angle;
  1243	    bool dirty;
  1244	
  1245	    if (view == NULL || !view->heading_up) {
  1246	        return;
  1247	    }
  1248	    /*
  1249	     * 角度待应用（want != rot），或 R 的烘焙角与当前角不一致（含烘焙失败回滚后
  1250	     * r_rot10 停在更早的值）⇒ 优先整幅：子矩形只能按 r_rot10 补，补完屏幕仍是旧朝向。
  1251	     */
  1252	    angle = (view->want_rot10 != view->rot10)
  1253	        || (view->r_rot10 != view->rot10);
  1254	    dirty = !vmap_rot_dirty_empty(view);
  1255	    if (!angle && !view->rot_pending && !dirty) {
  1256	        return;
  1257	    }
