  1259	        || view->render_rev == 0u
  1260	        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
  1261	        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
  1262	    }
  1263	
  1264	    /*
  1265	     * 整幅路径（保持原语义与 1200 ms 限频）：角度待应用，或只有"整幅待补"
  1266	     * 而没有具体区域（`vmap_view_stamp_nav_then_track` 的整画布重描）。
  1267	     */
  1268	    if (angle || view->rot_full_pending || !dirty) {
  1269	        if (view->last_bake_ms != 0u
  1270	            && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1271	            return;             /* 限频窗口未到：下一拍再来 */
  1272	        }
  1273	        /*
  1274	         * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
  1275	         * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
  1276	         * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
  1277	         * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
  1278	         */
  1279	        {
  1280	            const int32_t prev_rot10 = view->rot10;
  1281	
  1282	            view->rot10 = view->want_rot10;
  1283	            if (!vmap_rot_full(view)) {
  1284	                view->rot10 = prev_rot10;
  1285	            }
  1286	        }
  1287	        return;
  1288	    }
  1289	
  1290	    /*
  1291	     * 子矩形路径：角度没变、脏区明确 ⇒ 只重转这一块（典型 2~9 ms）。
  1292	     * 不刷新 `last_bake_ms`：子矩形不占用整幅限频窗口，否则持续增量会把角度
  1293	     * 重烘一直挡在窗口外。
  1294	     */
  1295	    if (vmap_rot_area(view)) {
  1296	        view->rot_pending = false;  /* R 已跟上 C 的脏区 */
  1297	        return;
  1298	    }
  1299	
  1300	    /*
  1301	     * 原语拒绝/参数失败/脏区过大：回退整幅。
  1302	     * 回退也走**同一个 1200 ms 限频窗口**（这就是本次改动之前"每个帧外增量都整幅
  1303	     * 重烘"的行为），否则一条持续的失败路径会变成每 200 ms 一次 138 ms 的整幅；
  1304	     * 窗口内没补成的保留 rot_dirty/rot_pending，下一拍再来。
  1305	     */
  1306	    if (view->last_bake_ms != 0u
  1307	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1308	        return;
  1309	    }
  1310	    vmap_rot_full(view);
  1311	}
