   706	  {
   707	    SRC_W = 32, SRC_H = 32, DST_W = 48, DST_H = 48, PIV = 16, ANGLE = 300,
   708	    PROBES = 10
   709	  };
   710	  static uint16_t src[SRC_W * SRC_H];
   711	  static uint16_t dst[DST_W * DST_H];
   712	  static const int16_t probe[PROBES][2] =
   713	  {
   714	    { 24, 24 }, { 24, 12 }, { 24, 36 }, { 12, 24 }, { 36, 24 },
   715	    { 16, 16 }, { 32, 32 }, { 32, 16 }, { 16, 32 }, { 24, 6 }
   716	  };
   717	  const int32_t cx = DST_W / 2;
   718	  const int32_t cy = DST_H / 2;
