   744	    {
   745	      /* 目的 (u,v) → 源：s = piv + R(-θ)·((u,v) - c)，θ 顺时针（y 向下）。 */
   746	      const double du = (double)(probe[i][0] - cx);
   747	      const double dv = (double)(probe[i][1] - cy);
   748	      const double sx = (double)PIV + (cos(th) * du + sin(th) * dv);
