   775	        }
   776	    }
   777	
   778	  syslog((fails == 0) ? LOG_NOTICE : LOG_WARNING,
   779	    "[vrot] selftest %s: %d probes, %d fail",
   780	    (fails == 0) ? "PASS" : "FAIL", (int)PROBES, (int)fails);
